 "content": "from collections import deque


def transform(grid):
    """Color one-cell rims of enclosed 1-outlined regions.

    A 4-connected zero component not reaching the grid edge is an enclosed
    cavity. For each cavity, its orthogonally adjacent 1-component is active.
    Zeros in the cavity's 8-neighbor rim become 3; exterior zeros in the
    active outline's 8-neighbor rim become 2.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    holes = []
    exterior = set()
    dirs4 = ((1, 0), (-1, 0), (0, 1), (0, -1))

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            comp = []
            touches_edge = False
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    touches_edge = True
                for dy, dx in dirs4:
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0 and not seen[yy][xx]:
                        seen[yy][xx] = True
                        q.append((yy, xx))
            if touches_edge:
                exterior.update(comp)
            else:
                holes.append(set(comp))

    if not holes:
        return out

    # A hole activates the orthogonally connected 1-boundary around it.
    ones_seen = [[False] * w for _ in range(h)]
    active_ones = set()
    for hole in holes:
        boundary = set()
        for r, c in hole:
            for dr, dc in dirs4:
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 1:
                    boundary.add((rr, cc))
        for r, c in boundary:
            if ones_seen[r][c]:
                active_ones.add((r, c))
                continue
            q = deque([(r, c)])
            ones_seen[r][c] = True
            while q:
                y, x = q.popleft()
                active_ones.add((y, x))
                for dy, dx in dirs4:
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 1 and not ones_seen[yy][xx]:
                        ones_seen[yy][xx] = True
                        q.append((yy, xx))

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            near_active = any(
                (r + dr, c + dc) in active_ones
                for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                if (dr or dc) and 0 <= r + dr < h and 0 <= c + dc < w
            )
            if not near_active:
                continue
            # Interior cavities are 3; only outside-facing cells are 2.
            if any((r, c) in hole for hole in holes):
                out[r][c] = 3
            elif (r, c) in exterior:
                out[r][c] = 2
    return out
